#include <iostream>
#include <sstream>
#include <string>
#include <vector>
#include <iomanip>

struct MasterRecord {
    int account{};
    std::string name;
    double balance{0.0};
};

struct TransactionRecord {
    int account{};
    double amount{0.0};
};

void matchFiles(std::istream& oldMast, std::istream& trans, std::ostream& newMast, std::ostream& errLog) {
    MasterRecord m;
    TransactionRecord t;
    bool hasM = static_cast<bool>(oldMast >> m.account >> m.name >> m.balance);
    bool hasT = static_cast<bool>(trans >> t.account >> t.amount);

    while (hasM && hasT) {
        if (m.account < t.account) {
            newMast << m.account << ' ' << m.name << ' ' << std::fixed << std::setprecision(2) << m.balance << '\n';
            hasM = static_cast<bool>(oldMast >> m.account >> m.name >> m.balance);
        } else if (m.account == t.account) {
            m.balance += t.amount;
            hasT = static_cast<bool>(trans >> t.account >> t.amount);
            while (hasT && t.account == m.account) {
                m.balance += t.amount;
                hasT = static_cast<bool>(trans >> t.account >> t.amount);
            }
            newMast << m.account << ' ' << m.name << ' ' << std::fixed << std::setprecision(2) << m.balance << '\n';
            hasM = static_cast<bool>(oldMast >> m.account >> m.name >> m.balance);
        } else {
            errLog << "Unmatched transaction record for account number " << t.account << '\n';
            hasT = static_cast<bool>(trans >> t.account >> t.amount);
        }
    }

    while (hasM) {
        newMast << m.account << ' ' << m.name << ' ' << std::fixed << std::setprecision(2) << m.balance << '\n';
        hasM = static_cast<bool>(oldMast >> m.account >> m.name >> m.balance);
    }

    while (hasT) {
        errLog << "Unmatched transaction record for account number " << t.account << '\n';
        hasT = static_cast<bool>(trans >> t.account >> t.amount);
    }
}

int main() {
    // Dữ liệu từ Bài tập 11.7 và 11.10
    std::string masterData =
        "100 Alan_Jones 348.17\n"
        "300 Mary_Smith 27.19\n"
        "500 Sam_Sharp 0.00\n"
        "700 Suzy_Green -14.22\n";

    std::string transData =
        "100 27.14\n"
        "300 62.11\n"
        "300 83.89\n"
        "400 100.56\n"
        "700 80.78\n"
        "700 1.53\n"
        "900 82.17\n";

    std::istringstream oldMastStream(masterData);
    std::istringstream transStream(transData);
    std::ostringstream newMastStream;
    std::ostringstream errStream;

    matchFiles(oldMastStream, transStream, newMastStream, errStream);

    std::cout << "=== NEW MASTER FILE ===\n" << newMastStream.str();
    std::cout << "=== ERROR LOG ===\n" << errStream.str();
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

// 1. Phone number letter mapping generator
const std::vector<std::string> keypad = {
    "", "", "ABC", "DEF", "GHI", "JKL", "MNO", "PRS", "TUV", "WXY"
};

void generateWords(const std::string& phone, size_t index, std::string& current, std::vector<std::string>& results) {
    if (index == phone.size()) {
        results.push_back(current);
        return;
    }
    int digit = phone[index] - '0';
    if (digit < 2 || digit > 9) return;
    for (char ch : keypad[digit]) {
        current.push_back(ch);
        generateWords(phone, index + 1, current, results);
        current.pop_back();
    }
}

// 2. Phishing scanner
struct PhishRule {
    std::string phrase;
    int points;
};

int main() {
    // Demo sinh từ cho 3 chữ số đầu để minh họa ngắn gọn (234: 3^3 = 27 từ)
    std::string testDigits = "234";
    std::vector<std::string> words;
    std::string current;
    generateWords(testDigits, 0, current, words);
    std::cout << "Generated words for prefix " << testDigits << " (count = " << words.size() << "):\n";
    std::cout << words[0] << " ... " << words.back() << "\n\n";

    // Demo quét phishing
    std::vector<PhishRule> rules = {
        {"verify your account", 3},
        {"urgent security notice", 3},
        {"bank of america", 2},
        {"password reset", 2},
        {"dear customer", 1}
    };

    std::string sampleEmail =
        "dear customer: urgent security notice from bank of america. "
        "please verify your account immediately by following the link.";

    int totalScore = 0;
    std::cout << "=== PHISHING SCAN RESULTS ===\n";
    for (const auto& rule : rules) {
        size_t count = 0;
        size_t pos = sampleEmail.find(rule.phrase);
        while (pos != std::string::npos) {
            ++count;
            pos = sampleEmail.find(rule.phrase, pos + rule.phrase.length());
        }
        if (count > 0) {
            int points = count * rule.points;
            totalScore += points;
            std::cout << "Match: '" << rule.phrase << "' | Count: " << count 
                      << " | Score: " << points << '\n';
        }
    }
    std::cout << "Total Threat Score: " << totalScore << '\n';
    return 0;
}
